131	export async function updateAllUpdatableExtensions(
132	  extensions: GeminiCLIExtension[],
133	  extensionsState: Map<string, ExtensionUpdateStatus>,
134	  extensionManager: ExtensionManager,
135	  dispatch: (action: ExtensionUpdateAction) => void,
136	  enableExtensionReloading?: boolean,
137	): Promise<ExtensionUpdateInfo[]> {
138	  return (
139	    await Promise.all(
140	      extensions
141	        .filter(
142	          (extension) =>
143	            extensionsState.get(extension.name)?.status ===
144	            ExtensionUpdateState.UPDATE_AVAILABLE,
145	        )
146	        .map((extension) =>
147	          updateExtension(
148	            extension,
149	            extensionManager,
150	            extensionsState.get(extension.name)!.status,
151	            dispatch,
152	            enableExtensionReloading,
153	          ),
154	        ),
155	    )
156	  ).filter((updateInfo) => !!updateInfo);
157	}
158	
159	export interface ExtensionUpdateCheckResult {
160	  state: ExtensionUpdateState;
161	  error?: string;
162	}
163	
164	export async function checkForAllExtensionUpdates(
165	  extensions: GeminiCLIExtension[],
166	  extensionManager: ExtensionManager,
167	  dispatch: (action: ExtensionUpdateAction) => void,
168	): Promise<void> {
169	  dispatch({ type: 'BATCH_CHECK_START' });
170	  try {
171	    const promises: Array<Promise<void>> = [];
172	    for (const extension of extensions) {
173	      if (!extension.installMetadata) {
174	        dispatch({
175	          type: 'SET_STATE',
176	          payload: {
177	            name: extension.name,
178	            state: ExtensionUpdateState.NOT_UPDATABLE,
179	          },
180	        });
181	        continue;
182	      }
183	      dispatch({
184	        type: 'SET_STATE',
185	        payload: {
186	          name: extension.name,
187	          state: ExtensionUpdateState.CHECKING_FOR_UPDATES,
188	        },
189	      });
190	      promises.push(
191	        checkForExtensionUpdate(extension, extensionManager).then((state) =>
192	          dispatch({
193	            type: 'SET_STATE',
194	            payload: { name: extension.name, state },
195	          }),
196	        ),
197	      );
198	    }
199	    await Promise.all(promises);
200	  } finally {
201	    dispatch({ type: 'BATCH_CHECK_END' });
202	  }
203	}
