122	  extensionManager: ExtensionManager,
123	  extensionName: string,
124	  scope: ExtensionSettingScope,
125	  logger: ConfigLogger = defaultLogger,
126	  requestSetting: RequestSettingCallback = defaultRequestSetting,
127	  requestConfirmation: RequestConfirmationCallback = defaultRequestConfirmation,
