160	export async function configureAllExtensions(
161	  extensionManager: ExtensionManager,
162	  scope: ExtensionSettingScope,
163	  logger: ConfigLogger = defaultLogger,
164	  requestSetting: RequestSettingCallback = defaultRequestSetting,
165	  requestConfirmation: RequestConfirmationCallback = defaultRequestConfirmation,
166	) {
167	  const extensions = extensionManager.getExtensions();
168	
169	  if (extensions.length === 0) {
170	    logger.log('No extensions installed.');
171	    return;
172	  }
173	
174	  for (const extension of extensions) {
175	    const extensionConfig = await extensionManager.loadExtensionConfig(
176	      extension.path,
177	    );
178	    if (
179	      extensionConfig &&
180	      extensionConfig.settings &&
181	      extensionConfig.settings.length > 0
182	    ) {
183	      logger.log(`\nConfiguring settings for "${extension.name}"...`);
184	      await configureExtensionSettings(
185	        extensionConfig,
186	        extension.id,
187	        scope,
188	        logger,
189	        requestSetting,
190	        requestConfirmation,
191	      );
192	    }
193	  }
