196	export async function configureExtensionSettings(
197	  extensionConfig: ExtensionConfig,
198	  extensionId: string,
199	  scope: ExtensionSettingScope,
200	  logger: ConfigLogger = defaultLogger,
201	  requestSetting: RequestSettingCallback = defaultRequestSetting,
202	  requestConfirmation: RequestConfirmationCallback = defaultRequestConfirmation,
203	) {
204	  const currentScopedSettings = await getScopedEnvContents(
205	    extensionConfig,
206	    extensionId,
207	    scope,
208	    process.cwd(),
209	  );
210	
211	  let workspaceSettings: Record<string, string> = {};
212	  if (scope === ExtensionSettingScope.USER) {
213	    workspaceSettings = await getScopedEnvContents(
214	      extensionConfig,
215	      extensionId,
216	      ExtensionSettingScope.WORKSPACE,
217	      process.cwd(),
218	    );
219	  }
220	
221	  if (!extensionConfig.settings) return;
222	
223	  for (const setting of extensionConfig.settings) {
224	    const currentValue = currentScopedSettings[setting.envVar];
225	    const workspaceValue = workspaceSettings[setting.envVar];
226	
227	    if (workspaceValue !== undefined) {
228	      logger.log(
229	        `Note: Setting "${setting.name}" is already configured in the workspace scope.`,
230	      );
231	    }
232	
233	    if (currentValue !== undefined) {
234	      const confirmed = await requestConfirmation(
235	        `Setting "${setting.name}" (${setting.envVar}) is already set. Overwrite?`,
236	      );
237	
238	      if (!confirmed) {
239	        continue;
240	      }
241	    }
242	
243	    await updateSetting(
244	      extensionConfig,
245	      extensionId,
246	      setting.envVar,
247	      requestSetting,
248	      scope,
249	      process.cwd(),
250	    );
251	  }
252	}
