37	/**
38	 * Manages the secret key used for signing integrity data.
39	 * Attempts to use the OS keychain, falling back to a restricted local file.
40	 * @internal
41	 */
42	class IntegrityKeyManager {
43	  private readonly fallbackKeyPath: string;
44	  private readonly keychainService: KeychainService;
45	  private cachedSecretKey: string | null = null;
46	
47	  constructor() {
48	    const configDir = path.join(homedir(), GEMINI_DIR);
49	    this.fallbackKeyPath = path.join(configDir, INTEGRITY_KEY_FILENAME);
50	    this.keychainService = new KeychainService(KEYCHAIN_SERVICE_NAME);
51	  }
52	
53	  /**
54	   * Retrieves or generates the master secret key.
55	   */
56	  async getSecretKey(): Promise<string> {
57	    if (this.cachedSecretKey) {
58	      return this.cachedSecretKey;
59	    }
60	
61	    if (await this.keychainService.isAvailable()) {
62	      try {
63	        this.cachedSecretKey = await this.getSecretKeyFromKeychain();
64	        return this.cachedSecretKey;
65	      } catch (e) {
66	        debugLogger.warn(
67	          `Keychain access failed, falling back to file-based key: ${getErrorMessage(e)}`,
